/* Accessory lessons are appended to each verified compatible controller only. */
function buildRemoteCurriculum(profile){
 const configs=typeof module!=='undefined'?require('./remote-controls.js').rinkRemoteProfiles:rinkRemoteProfiles,c=configs[profile];if(!c)return [];
 const lessons=[],add=(id,title,text,task,solution,check,setup=()=>{})=>lessons.push({group:'Remote controls',id:'remote-'+id,title,text,task,solution,setup,check:(s,e,h)=>e!=='initial'&&check(s.remote,s.model,e,h)});
 const connected=s=>s.remote.command('connect');
 add('connect','Connect the optional accessory','Open Remote controls below the console. Attach the selected training accessory with the timer stopped.','Remote controls → Connect accessory',['remote:connect'],(r,m,e)=>e==='remote:connect'&&r.connected);
 add('run-stop',profile==='vision'?'Use the external run/hold switch':'Run and stop with the handset',profile==='vision'?'Each press toggles the timer. The console controls remain available.':'The clock switch is maintained: ON starts timing; OFF stops it.','Connect accessory → '+(profile==='vision'?'RUN / HOLD':'CLOCK ON')+' → wait → '+(profile==='vision'?'RUN / HOLD':'CLOCK OFF'),['remote:connect','remote:toggle','tick:1','remote:toggle'],(r,m,e)=>e==='remote:toggle'&&!m.running&&m.time<900);
 add('disconnect','Disconnect the accessory','Disconnecting in this trainer stops the timer. Check the profile note for console recovery requirements.','Connect accessory → Disconnect accessory',['remote:connect','remote:disconnect'],(r,m,e)=>e==='remote:disconnect'&&!r.connected&&!m.running);
 if(['gameHorn'].includes(c.devices[0].type))add('horn','Use the remote horn','Press and hold the remote horn. It is independent of the console auto-horn option. Nevco TCS-5/7 limit a blast to four seconds.','Connect accessory → hold HORN',['remote:connect','remote:hornDown','remote:hornUp'],(r,m,e)=>e==='remote:hornUp'&&!r.hornHeld);
 if(profile.startsWith('nevco')){
  add('panel-lock','Recognize the panel interlock','With the handset connected, the console time keys do not start the clock. Use the handheld instead.','Connect accessory → try console '+(profile==='nevco4'?'alternate time':'TIME ON')+' → remote CLOCK ON',['remote:connect',profile==='nevco4'?'rocker':'run','remote:toggle'],(r,m,e)=>e==='remote:toggle'&&r.locked&&m.running);
  if(c.restart){
   add('unplug-lock','Understand why unplugging is not enough','TCS-5/7 lock out console TIME ON/OFF until the console is restarted after disconnecting.','Connect → Disconnect → try console TIME ON',['remote:connect','remote:disconnect','run'],(r,m,e)=>e==='key:run'&&!r.connected&&r.locked&&!m.running);
   add('restart','Restore console time controls','The manual permits restarting and resuming the saved game. This practice action retains time, score and penalties.','Connect → Disconnect → Restart console · keep game → TIME ON',['remote:connect','remote:disconnect','remote:restart','run'],(r,m,e)=>e==='key:run'&&!r.locked&&m.running&&m.home===2,s=>{s.model.home=2;});
  }else add('alternate-restore','Restore the MPC-4 alternate switch','The MPC-4 instructions describe the alternate switch being disabled while the TCS-1 is plugged in.','Connect → Disconnect → alternate time switch ON',['remote:connect','remote:disconnect','rocker'],(r,m,e)=>e==='key:rocker'&&!r.locked&&m.running);
 }
 if(profile==='isc9000'){
  add('wired-shots','Use a wired shots accessory','This fixed ISCREM-P assignment increments home and guest shots. It does not change either score.','Accessory → ISCREM-P shots → Connect → HOME +1 → GUEST +1',['remote:device:iscrem-sog','remote:connect','remote:homeAdd','remote:guestAdd'],(r,m,e)=>e==='remote:guestAdd'&&m.shots.home===1&&m.shots.guest===1&&m.home===0);
  add('wireless-game','Use ISC-HH GAME mode','The controller must be configured for GAME. Pairing is assumed complete in this simulator. The handheld layout is functional.','Accessory → ISC-HH GAME → Connect → HOME +1 → GUEST +1',['remote:device:ischh-game','remote:connect','remote:scoreHome','remote:scoreGuest'],(r,m,e)=>e==='remote:scoreGuest'&&m.home===1&&m.guest===1);
  add('wireless-reset','Reset time and scores with ISC-HH','GAME mode can reset the game timer and each team’s score. Stop the timer first.','Accessory → ISC-HH GAME → Connect → RESET TIME → RESET HOME → RESET GUEST',['remote:device:ischh-game','remote:connect','remote:resetTime','remote:resetHome','remote:resetGuest'],(r,m,e)=>e==='remote:resetGuest'&&m.time===900&&m.home===0&&m.guest===0,s=>{s.model.time=60;s.model.home=2;s.model.guest=3;});
  add('wireless-shots','Correct shots with ISC-HH SOG mode','SOG mode adds and subtracts shots, without changing goals.','Accessory → ISC-HH SOG → Connect → HOME +1 → HOME −1 → GUEST +1 → GUEST −1',['remote:device:ischh-sog','remote:connect','remote:homeAdd','remote:homeSubtract','remote:guestAdd','remote:guestSubtract'],(r,m,e)=>e==='remote:guestSubtract'&&m.shots.home===0&&m.shots.guest===0);
 }
 if(profile==='vision'){
  add('aux-shots','Use the auxiliary shots box','The optional shots box has HOME, GUEST and DOWN buttons. It is separate from the external timer toggle.','Accessory → Auxiliary shots box → Connect → HOME → GUEST',['remote:device:vision-sog','remote:connect','remote:homeDown','remote:homeUp','remote:guestDown','remote:guestUp'],(r,m,e)=>e==='remote:guestUp'&&m.shots.home===1&&m.shots.guest===1);
  add('aux-subtract','Hold DOWN to correct shots','Keep DOWN held while pressing a team button. Counts cannot fall below zero.','Auxiliary shots box → Connect → hold DOWN → HOME → release both',['remote:device:vision-sog','remote:connect','remote:modifierDown','remote:homeDown','remote:homeUp','remote:modifierUp'],(r,m,e)=>e==='remote:modifierUp'&&m.shots.home===2&&!r.modifier,s=>{s.model.shots.home=3;});
  add('aux-reset','Clear both shots totals','The physical shortcut holds HOME, GUEST and DOWN together. The practice helper makes that gesture accessible on a keyboard too.','Auxiliary shots box → Connect → Simulate all three held',['remote:device:vision-sog','remote:connect','remote:allShots'],(r,m,e)=>e==='remote:allShots'&&m.shots.home===0&&m.shots.guest===0,s=>{s.model.shots.home=5;s.model.shots.guest=4;});
 }
 if(profile==='fairplay'){
  add('console-off','Leave console TIME IN at OFF','For a wired HH-70/HC-70 handset, the manual requires console TIME OUT. A console switch left ON prevents remote OFF stopping play.','Connect HH-70 → console TIME IN ON → remote CLOCK ON → remote CLOCK OFF',['remote:connect','run','remote:toggle','remote:toggle'],(r,m,e)=>e==='remote:toggle'&&r.panelOn&&m.running);
  add('recover-off','Stop a wired timer from both switches','Turn console TIME IN off as well as the remote.','Connect → console TIME IN ON → remote ON → remote OFF → console TIME IN OFF',['remote:connect','run','remote:toggle','remote:toggle','hold'],(r,m,e)=>e==='key:hold'&&!m.running&&!r.on&&!r.panelOn);
  add('clock-reset','Use HC-70 clock reset','HC-70 replaces the horn pushbutton with RESET. Both maintained switches must be OFF.','Accessory → HC-70 → Connect → RESET CLOCK',['remote:device:hc70','remote:connect','remote:resetTime'],(r,m,e)=>e==='remote:resetTime'&&m.time===900,s=>{s.model.time=60;});
  add('miclock','Enable compatible MiClock remote mode','This selects the compatible MP-72-2211/-2213 training variant (firmware 2.25+). It is not an MP-50 feature.','Accessory → MiClock MC-10 → Connect → console SHIFT → 1 → YES → remote CLOCK ON',['remote:device:miclock','remote:connect','shift','1','yes','remote:toggle'],(r,m,e)=>e==='remote:toggle'&&r.exclusive&&m.running);
  add('miclock-console','Restore console mode','NO at the MiClock prompt selects console control again.','MiClock accessory → Connect → SHIFT → 1 → NO → console TIME IN ON',['remote:device:miclock','remote:connect','shift','1','no','run'],(r,m,e)=>e==='key:run'&&!r.exclusive&&m.running);
 }
 return lessons;
}
if(typeof module!=='undefined')module.exports=buildRemoteCurriculum;
else{const beforeRemotes=buildCurriculum;buildCurriculum=profile=>[...beforeRemotes(profile),...buildRemoteCurriculum(profile)];}
